-- Generated by ekos-lakehouse (RFC 0195) from marts/rentals_by_store_month.md. Approve by merging; do not edit.
{{ config(materialized='table', schema='gold', alias='rentals_by_store_month') }}

select
    "inventory"."store_id" as "store",
    date_trunc('month', "rental"."rented_at") as "month",
    count("rental"."rental_id") as "rentals"
from {{ ref('public__rental') }} as "rental"
left join {{ ref('public__inventory') }} as "inventory"
    on "rental"."inventory_id" = "inventory"."inventory_id"
group by "inventory"."store_id", date_trunc('month', "rental"."rented_at")
